import{createTruforAnalyzer}from'./trufor-analyzer.js';
import{compileOriginalSourceRegions}from'./source-region-geometry.js';
import{createSourceRegionView}from'./source-region-view.js';
import{sourceRegionTransportBytes}from'./source-region-transport.js';
import{EngineError,requireValue,checkAbort}from'./errors.js';
import{truforStrictParameters,planTruforStrictContexts,truforStrictField}from'./trufor-strict-contexts.js';
import{renderTruforStrictWindow}from'./trufor-strict-render.js';
import{bindTruforStrictResult}from'./trufor-strict-result.js';

/** One unchanged native analyzer/pool set. Each strict context retains the
 * real native output loan; no aggregate score, image resampling or second CNN. */
export function createTruforStrictAnalyzer({budget,analyzer,analyzerFactory=createTruforAnalyzer,...configuration}={}){
 requireValue(budget,'An explicit TruFor budget is required.');const native=analyzer??analyzerFactory({...configuration,budget}),owners=new Set(),pendingViews=new Set();let active,disposed=false,cached;
 async function retire(entry){if(entry.refs||entry.closed)return;if(entry.retiring)return entry.retiring;entry.retiring=(async()=>{const failures=[];for(const part of entry.parts)if(!part.closed)try{await part.value.release();part.closed=true;}catch(error){failures.push(error);}if(failures.length)throw failures[0];for(const lease of entry.leases)lease();entry.leases.length=0;entry.parts.length=0;entry.closed=true;owners.delete(entry);})();try{await entry.retiring;}finally{entry.retiring=null;}}
 async function retireView(view){if(!view)return;try{await view.dispose();pendingViews.delete(view);}catch(error){pendingViews.add(view);throw error;}}

 async function unpin(entry){requireValue(entry.refs>0,'Native TruFor loan is already retired.');entry.refs--;await retire(entry);}
 function acquire(entry,hit,image){requireValue(!entry.closed,'Native TruFor context owner is closed.');const lease=budget.reserve(entry.scores.byteLength+16384+sourceRegionTransportBytes(entry.metadata,{allowUndefined:true,allowAliases:true})*3+sourceRegionTransportBytes(entry.provenance,{allowUndefined:true,allowAliases:true})*3);let released=false,closing=false,completion;const reads=new Set(),withRead=fn=>{requireValue(!closing,'Native TruFor result is retiring.');const promise=Promise.resolve().then(fn);reads.add(promise);promise.finally(()=>reads.delete(promise)).catch(()=>{});return promise;};
  try{const alive=()=>requireValue(!released&&!entry.closed,'Native TruFor result is retired.');
   const result={data:{width:entry.domain.width,height:entry.domain.height,segmented:true,pixelCount:entry.plan.pixels,map:truforStrictField(entry.parts,'map',entry.plan.pixels,{alive,withRead}),confidence:truforStrictField(entry.parts,'confidence',entry.plan.pixels,{alive,withRead}),noiseprint_pp:truforStrictField(entry.parts,'noiseprint_pp',entry.plan.pixels,{alive,withRead}),context_scores:entry.scores.slice(),metadata:structuredClone(entry.metadata)},provenance:structuredClone(entry.provenance),metrics:{nativeContexts:entry.plan.fragments.length,evaluatedContexts:entry.parts.length,nonEvaluableContexts:entry.plan.fragments.length-entry.parts.length,sourceRegionEvaluation:entry.metadata.sourceRegionEvaluation,selectedPixels:entry.plan.selectedPixels,analysedPixels:entry.plan.pixels,unanalysablePixels:entry.plan.selectedPixels-entry.plan.pixels,cache:{result:hit},preflightExecutions:0,memory:budget.snapshot()},release(){if(completion)return completion;closing=true;completion=(async()=>{await Promise.allSettled([...reads]);released=true;try{await unpin(entry);}finally{lease();}})();return completion;}};
   bindTruforStrictResult(result,{domain:entry.domain,parts:entry.parts,image,withRead,released:()=>released||entry.closed});entry.refs++;return result;
  }catch(error){lease();throw error;}
 }

 const clearNative=()=>native.clearCache();
 return{
  async analyze(image,params={},options={}){
   options={...options};image={...image,...image?.surface?{surface:{...image.surface,descriptor:Object.freeze({...image.surface.descriptor})}}:{},...image?.presentationSurface?{presentationSurface:{...image.presentationSurface,descriptor:Object.freeze({...image.presentationSurface.descriptor})}}:{}};
   if(disposed)throw new EngineError('DISPOSED','Strict TruFor analyzer is closed.');if(active)throw new EngineError('BUSY','Strict TruFor analysis is active.');const parameters=truforStrictParameters(params),controller=new AbortController(),abort=()=>controller.abort();let finish;active={controller,done:new Promise(r=>finish=r)};options.signal?.addEventListener('abort',abort,{once:true});if(options.signal?.aborted)abort();const leases=[];let view,entry,current,answer,primary;
   try{
    checkAbort(controller.signal);const input=options.sourceRegionDomain??image.sourceRegionDomain??image.provenance?.sourceRegionDomain;leases.push(budget.reserve(sourceRegionTransportBytes(input,{allowUndefined:true,allowAliases:true})*8+65536));const domain=await compileOriginalSourceRegions(input);checkAbort(controller.signal);const d=image.surface?.descriptor;requireValue(image.sha256===domain.sourceSha256&&d?.width===domain.sourceWidth&&d.height===domain.sourceHeight,'Strict TruFor requires the actual Original surface, source identity and grid.');
    if(domain.empty)throw new EngineError('SOURCE_SCOPE_EMPTY','TruFor selection has no admitted pixels.');const key=JSON.stringify([image.sha256,domain.fingerprint,d.id,d.revision,options.backend??'auto']);if(cached?.key===key){answer=acquire(cached,true,image);return answer;}
    view=await createSourceRegionView({...image.surface,sha256:image.sha256},domain.descriptor,{budget,signal:controller.signal,maxReadPixels:2**30});const plan=await planTruforStrictContexts(view,{budget,signal:controller.signal});leases.push(plan.release);leases.push(budget.reserve(65536));entry={key,domain,plan,parts:[],leases:[],refs:0,closed:false};owners.add(entry);const scores=new Float64Array(plan.fragments.filter(f=>f.evaluable).length),executions=[];
    for(const fragment of plan.fragments){if(!fragment.evaluable)continue;checkAbort(controller.signal);const r=fragment.rect,surface={descriptor:Object.freeze({id:'trufor-strict/'+domain.fingerprint+'/'+[r.x,r.y,r.width,r.height].join(','),revision:1,width:r.width,height:r.height,format:'rgb8'}),readWindow:(rect,hooks)=>view.readWindow({...rect,x:rect.x+r.x,y:rect.y+r.y},hooks)};
     current=await native.analyze({width:r.width,height:r.height,sha256:image.sha256,surface},parameters,{...options,immutableSource:false,signal:controller.signal});checkAbort(controller.signal);const data=current.data;requireValue(data?.segmented===true&&data.width===r.width&&data.height===r.height&&Number.isFinite(data.score),'Native TruFor geometry/score differs from its strict context.');for(const name of['map','confidence','noiseprint_pp'])requireValue(data[name]?.length===fragment.count&&data[name].width===r.width&&data[name].height===r.height&&data[name].channels===1&&data[name].byteLength===fragment.count*4&&typeof data[name].readBytes==='function'&&typeof data[name].readInto==='function','Native TruFor map geometry differs from its context.');
     scores[entry.parts.length]=data.score;const receipt={fragment:fragment.index,score:data.score,provenance:current.provenance??{},metrics:current.metrics??{}};leases.push(budget.reserve(sourceRegionTransportBytes(receipt,{allowUndefined:true,allowAliases:true})*3+4096));executions.push(structuredClone(receipt));entry.parts.push({fragment,value:current,closed:false});current=null;options.onProgress?.({phase:'trufor-native-contexts',completed:fragment.index+1,total:plan.fragments.length});
    }
    checkAbort(controller.signal);const unavailable=plan.fragments.length-entry.parts.length,evaluation=!plan.pixels?'native-not-evaluable':unavailable?'partially-evaluable':'complete';entry.scores=scores;entry.metadata={method:'trufor',fragmented:true,rgbDivisor:256,attention:'global-within-each-native-context',statisticsPooling:'unchanged complete native context; no pooled union score',threshold:null,sourceRegionOrigin:[...domain.origin],originalShape:[domain.sourceHeight,domain.sourceWidth],fragments:plan.fragments,sourceRegionEvaluation:evaluation,selectedPixels:plan.selectedPixels,modeledPixels:plan.pixels,nonEvaluatedSelectedPixels:plan.selectedPixels-plan.pixels,arrayLayout:'packed independent native context pixels; not an image grid',scoreLayout:'one native score per evaluable context in fragment order; no global scalar'};
    entry.provenance={adapter:'trufor-strict-native-contexts-experimental',qualification:'native-model qualification pending',originalSourceSha256:domain.sourceSha256,sourceRegionDomain:domain.descriptor,nativeParameters:{},executions};entry.leases=leases.splice(0);entry.refs=1;try{answer=acquire(entry,false,image);}catch(error){entry.refs=0;throw error;}const old=cached;cached=entry;entry=null;if(old)await unpin(old);return answer;
   }catch(error){primary=error;throw error;}finally{
    const failures=[];for(const action of[()=>current?.release(),()=>entry&&retire(entry),()=>retireView(view),...leases])try{await action();}catch(error){failures.push(error);}options.signal?.removeEventListener('abort',abort);const lateAbort=!primary&&controller.signal.aborted?new EngineError('CANCELLED','TruFor request cancelled before completion.'):null;if((primary||lateAbort||failures.length)&&answer)try{await answer.release();}catch(error){failures.push(error);}active=null;finish();if(lateAbort){if(failures.length)lateAbort.cleanupError=failures[0];throw lateAbort;}if(failures.length){if(primary&&Object.isExtensible(primary))primary.cleanupError=failures[0];else throw failures[0];}
   }
  },
  renderWindow(image,result,view,rect,options={}){return renderTruforStrictWindow(image,result,view,rect,{...options,budget,native});},
  render(image,result,view='map',options={}){return this.renderWindow(image,result,view,{x:0,y:0,width:result.data.width,height:result.data.height},options);},
  async clearCache(){const old=cached;cached=null;const failures=[];if(old)try{await unpin(old);}catch(e){failures.push(e);}try{await clearNative();}catch(e){failures.push(e);}for(const e of owners)if(!e.refs)try{await retire(e);}catch(error){failures.push(error);}for(const view of pendingViews)try{await retireView(view);}catch(error){failures.push(error);}if(failures.length)throw failures[0];},
  async dispose(){if(disposed)return;disposed=true;const pending=active;pending?.controller.abort();await pending?.done;let failure;try{await this.clearCache();}catch(error){failure=error;}try{await native.dispose();}catch(error){failure??=error;}if(failure)throw failure;},
  memory(){return budget.snapshot();}
 };
}
